/// The values of `connectors.removal_cause`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Serialize)]
pub enum RemovalCause {
    /// The member who connected it disconnected it (connectors.disconnect).
    #[serde(rename = "disconnected")]
    Disconnected,
    /// The member who connected it left the workspace or was removed (workspaces.member_left).
    #[serde(rename = "member_left")]
    MemberLeft,
}

/// The values of `connectors.send_error`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Serialize)]
pub enum SendError {
    /// The connection needs the member again.
    #[serde(rename = "needs_reauth")]
    NeedsReauth,
    /// The inbox's connection is gone, or its provider is not configured.
    #[serde(rename = "not_connected")]
    NotConnected,
    /// A reason this plan does not know yet.
    #[serde(rename = "other")]
    Other,
    /// The provider refused it.
    #[serde(rename = "rejected")]
    Rejected,
    /// Too large for the provider.
    #[serde(rename = "too_large")]
    TooLarge,
    /// The provider could not be reached, or the send no longer stands; nothing was sent.
    #[serde(rename = "unavailable")]
    Unavailable,
    /// It may have been sent: an attempt ended with no clear answer.
    #[serde(rename = "unknown_outcome")]
    UnknownOutcome,
}

/// The values of `connectors.send_state`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Serialize)]
pub enum SendState {
    /// It failed for good.
    #[serde(rename = "failed")]
    Failed,
    /// Not settled yet.
    #[serde(rename = "pending")]
    Pending,
    /// The provider has it.
    #[serde(rename = "sent")]
    Sent,
}

/// The values of `connectors.sent_copy`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Serialize)]
pub enum SentCopy {
    /// Appended to Sent.
    #[serde(rename = "appended")]
    Appended,
    /// Appending it kept failing.
    #[serde(rename = "failed")]
    Failed,
    /// Already in Sent.
    #[serde(rename = "found")]
    Found,
    /// The stream's next run appends it to Sent.
    #[serde(rename = "pending")]
    Pending,
    /// The SMTP server keeps one itself.
    #[serde(rename = "provider")]
    Provider,
    /// No copy is made.
    #[serde(rename = "skipped")]
    Skipped,
}
